package com.nextaicommerce.platform.fba;
import java.util.*;import java.math.BigDecimal;import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
import org.springframework.jdbc.core.JdbcTemplate;import tools.jackson.databind.ObjectMapper;import com.nextaicommerce.platform.receiving.InventoryRepository;
import static com.nextaicommerce.platform.fba.FbaInboundWorkflow.*;import static com.nextaicommerce.platform.fba.FbaInboundOrchestration.*;
class FbaInboundCheckpointsTest {
 final UUID tenant=UUID.randomUUID(),store=UUID.randomUUID(),planId=UUID.randomUUID(),warehouse=UUID.randomUUID(),item=UUID.randomUUID(),user=UUID.randomUUID();final Scope scope=new Scope(tenant,tenant,store,planId);final ObjectMapper json=new ObjectMapper();
 JdbcTemplate jdbc;FbaReplenishmentPlans plans;FbaInboundCheckpoints checkpoints;FbaReplenishmentPlans.Plan plan;
 @BeforeEach void setup(){jdbc=mock(JdbcTemplate.class);plans=spy(new FbaReplenishmentPlans(jdbc,json,mock(InventoryRepository.class)));checkpoints=new FbaInboundCheckpoints(plans,jdbc,json);plan=new FbaReplenishmentPlans.Plan(planId,"FBA001","ALLOCATED",1,2,Map.of(),List.of(allocation(item,4,8)),List.of());doReturn(plan).when(plans).read(eq(tenant),eq(store),eq(planId),anyBoolean());doReturn(user).when(plans).actor("operator@example.test");when(jdbc.queryForObject(startsWith("SELECT EXISTS(SELECT 1 FROM warehouses"),eq(Boolean.class),eq(tenant),eq(warehouse))).thenReturn(true);}
 Map<String,Object> allocation(UUID product,int ratio,int quantity){return Map.of("warehouse_id",warehouse,"seller_sku","PACK","account_catalog_item_id",product,"each_per_sku",ratio,"quantity",quantity,"dispatched",0,"reservation_status","ACTIVE");}
 Audit audit(String kind){return new Audit(UUID.randomUUID(),kind,"operator@example.test",Map.of());}
 @Test void accountCannotBeSwappedForParentOrAnotherAccount(){assertThrows(RuntimeException.class,()->checkpoints.read(new Scope(tenant,UUID.randomUUID(),store,planId),warehouse));verify(plans,never()).read(any(),any(),any(),anyBoolean());}
 @Test void originRequiresManagedWarehouseAndCompleteAllocation(){assertEquals(2,FbaInboundCheckpoints.originUnits(plan,warehouse).get("PACK"));assertThrows(RuntimeException.class,()->checkpoints.read(scope,UUID.randomUUID()));var incomplete=new FbaReplenishmentPlans.Plan(planId,"FBA001","ALLOCATED",1,2,Map.of(),List.of(allocation(item,4,7)),List.of());assertThrows(RuntimeException.class,()->FbaInboundCheckpoints.originUnits(incomplete,warehouse));}
 @Test void staleRevisionNeverExecutesTransitionOrWritesCheckpoint(){var calls=new AtomicInteger();assertThrows(RuntimeException.class,()->checkpoints.mutate(scope,warehouse,0,audit("INBOUND_PENDING"),state->{calls.incrementAndGet();return state;}));assertEquals(0,calls.get());verify(jdbc,never()).update(startsWith("UPDATE fba_replenishment_plans"),any(Object[].class));}
 @Test void userCannotUseInternalRevisionBypass(){assertThrows(RuntimeException.class,()->checkpoints.mutate(scope,warehouse,-1,audit("INBOUND_PENDING"),state->state));verify(plans,never()).lock(any());}
 @Test void mutationPersistsCheckpointAndAuditBeforeReturning(){var result=checkpoints.mutate(scope,warehouse,1,audit("INBOUND_OPTIONS"),state->state);assertEquals(2,result.revision());verify(jdbc).update(startsWith("UPDATE fba_replenishment_plans SET checkpoint="),any(Object[].class));verify(jdbc).update(startsWith("INSERT INTO fba_replenishment_actions"),any(Object[].class));}
 @Test void replayReturnsLatestStateWithoutRepeatingTransition(){var audit=audit("INBOUND_STATUS_PENDING");doReturn(true).when(plans).replay(eq(tenant),eq(planId),eq(audit.requestId()),eq(audit.kind()),any());var calls=new AtomicInteger();assertEquals(1,checkpoints.mutate(scope,warehouse,-1,audit,state->{calls.incrementAndGet();return state;}).revision());assertEquals(0,calls.get());verify(jdbc,never()).update(startsWith("UPDATE fba_replenishment_plans"),any(Object[].class));}
 @Test void changedOriginScopeCannotBePersisted(){assertThrows(RuntimeException.class,()->checkpoints.mutate(scope,warehouse,1,audit("INBOUND_OPTIONS"),state->Checkpoint.initial(new Scope(tenant,tenant,UUID.randomUUID(),planId),warehouse)));verify(jdbc,never()).update(startsWith("UPDATE fba_replenishment_plans"),any(Object[].class));}
 @Test void jsonRoundTripPreservesRequestAndChildIdentities(){var request=UUID.randomUUID();var origin=start(scope,warehouse);origin=begin(origin,request,FbaInboundAdapter.Operation.CREATE,null,null,false,java.time.Instant.now());var stored=new Checkpoint(origin,Map.of(request,new Acknowledgement("operation","plan")),Map.of());var encoded=json.readValue(json.writeValueAsString(stored),Checkpoint.class);assertEquals(stored,encoded);assertTrue(encoded.origin().attempts().containsKey(request));}

 Origin cancelledOrigin(){UUID request=UUID.randomUUID();return new Origin(scope,warehouse,1,"verified-plan",Map.of(request,new Attempt(request,FbaInboundAdapter.Operation.CANCEL,null,1,null,Status.SUCCEEDED,"verified-cancel-operation")),Map.of(),Map.of(),List.of());}
 @Test void verifiedOriginCancellationReleasesOnlyOwnUndispatchedReservationAndNeverRestoresStock(){
  var cancelled=cancelledOrigin();checkpoints.mutate(scope,warehouse,-1,audit("INBOUND_STATUS_SUCCEEDED"),state->new Checkpoint(cancelled,Map.of(),Map.of()));
  verify(jdbc).update(startsWith("UPDATE order_inventory_reservations r SET status='RELEASED'"),eq(tenant),eq(store),eq(planId),eq(warehouse));verify(jdbc,never()).update(startsWith("INSERT INTO inventory_ledger_entries"),any(Object[].class));
  var update=org.mockito.ArgumentCaptor.forClass(Object[].class);verify(jdbc).update(startsWith("UPDATE fba_replenishment_plans SET checkpoint="),update.capture());assertEquals("CANCELLED",update.getValue()[2]);
 }
 @Test void cancellingOneOriginDoesNotCancelAnotherAllocatedWarehouse(){
  UUID second=UUID.randomUUID();var other=new HashMap<>(allocation(UUID.randomUUID(),1,2));other.put("warehouse_id",second);plan=new FbaReplenishmentPlans.Plan(planId,"FBA001","ALLOCATED",1,3,Map.of(),List.of(allocation(item,4,8),other),List.of());doReturn(plan).when(plans).read(eq(tenant),eq(store),eq(planId),anyBoolean());when(jdbc.queryForObject(startsWith("SELECT CASE WHEN EXISTS"),eq(String.class),any(Object[].class))).thenReturn("ALLOCATED");
  checkpoints.mutate(scope,warehouse,-1,audit("INBOUND_STATUS_SUCCEEDED"),state->new Checkpoint(cancelledOrigin(),Map.of(),Map.of()));var update=org.mockito.ArgumentCaptor.forClass(Object[].class);verify(jdbc).update(startsWith("UPDATE fba_replenishment_plans SET checkpoint="),update.capture());assertEquals("ALLOCATED",update.getValue()[2]);verify(jdbc).update(startsWith("UPDATE order_inventory_reservations r SET status='RELEASED'"),eq(tenant),eq(store),eq(planId),eq(warehouse));
 }
 @Test void cancelledHistoricalOriginRemainsReadableButCannotMutate(){
  var released=new HashMap<>(allocation(item,4,8));released.put("reservation_status","RELEASED");plan=new FbaReplenishmentPlans.Plan(planId,"FBA001","CANCELLED",2,5,Map.of("inboundOrigins",Map.of(warehouse.toString(),new Checkpoint(cancelledOrigin(),Map.of(),Map.of()))),List.of(released),List.of());doReturn(plan).when(plans).read(eq(tenant),eq(store),eq(planId),anyBoolean());assertEquals("verified-plan",checkpoints.read(scope,warehouse).checkpoint().origin().amazonPlanId());assertThrows(RuntimeException.class,()->checkpoints.mutate(scope,warehouse,2,audit("INBOUND_OPTIONS"),state->state));
 }
 @Test void childrenCannotClaimMoreThanConfirmedOriginContents(){
  assertThrows(RuntimeException.class,()->checkpoints.mutate(scope,warehouse,1,audit("INBOUND_OPTIONS"),state->new Checkpoint(new Origin(scope,warehouse,1,"verified-plan",Map.of(),Map.of("child",new Child("child",Map.of("PACK",3))),Map.of(),List.of()),Map.of(),Map.of())));verify(jdbc,never()).update(startsWith("UPDATE fba_replenishment_plans"),any(Object[].class));
 }
}
